export const SHARE_CHARTS_ENABLED = true;
/**
 * flavorDisplay.js — AROMA-4. THE display rule for flavor charts, written once. Pure, no imports (the share card
 * layout module is copied into the Cloud Functions package, and scripts/buildShareIndex.mjs inlines this file
 * into that copy, so keep it self-contained).
 *
 * This is an INTERIM rule: with six tastes and eleven aromas a full chart has seventeen bars, so every surface
 * shows only the strongest, until the owner picks a real redesign (plan.md CHART-1).
 *
 * The rule, in plain words
 *   1. Tastes and aromas are two groups ("Taste", "Aroma"), each ordered strongest first.
 *   2. A bar is shown only when its score is at least FLOOR (0.05, the floor the invent panels, the shared page
 *      and the cards already used).
 *   3. Each group has a maximum that depends on the surface's room (SURFACES below). When bars are hidden a short
 *      line says so ("+3 fainter notes"); surfaces with room (compact, full) also offer "show all".
 *   4. Ties are broken one way everywhere: scores are compared at 3 decimal places, and a tie goes to the axis
 *      that comes first in AXES (the canonical order: sweet, sour, bitter, salty, umami, heat, then fruity,
 *      floral, green, woody, spice, creamy, toasty, nutty, earthy, smoky, savory).
 *   5. A radar plots only the axes the rule selects for it (so a recipe's radar has 3 to 8 spokes, never 17).
 */

export const TASTE_AXES = ['sweet', 'sour', 'bitter', 'salty', 'umami', 'heat'];
export const AROMA_AXES = ['odor_fruity', 'odor_floral', 'odor_green', 'odor_woody', 'odor_spicy', 'odor_fatty', 'odor_toasty', 'odor_nutty', 'odor_earthy', 'odor_smoky', 'odor_savory'];
export const AXES = [...TASTE_AXES, ...AROMA_AXES];

/** Chart labels as drawn (recipeScoring.AROMA_LABELS): used to read a group off a bar that carries only a label. */
const LABEL_TO_AXIS = {
  sweet: 'sweet', sour: 'sour', bitter: 'bitter', salty: 'salty', umami: 'umami', heat: 'heat',
  fruity: 'odor_fruity', floral: 'odor_floral', green: 'odor_green', woody: 'odor_woody', spice: 'odor_spicy',
  creamy: 'odor_fatty', toasty: 'odor_toasty', nutty: 'odor_nutty', earthy: 'odor_earthy', smoky: 'odor_smoky', savory: 'odor_savory',
};

/** Below this a bar is not drawn. */
export const FLOOR = 0.05;

/**
 * How many bars of each group a surface shows.
 *   card     the share cards (preview, portrait, tall): 3 + 3 (the headings and the caption take room)
 *   cover    the first card of a set of three: 4 + 4
 *   compact  invent panels, shared page: 4 + 4, with "show all"
 *   full     the Recipe Notebook overview: 6 + 6, with "show all"
 *   radar    a radar plots at most 4 + 4 spokes (never fewer than MIN_SPOKES)
 *   mini     the 132 px radar on a suggestion card: 3 + 3
 */
export const SURFACES = {
  card: { taste: 3, aroma: 3, showAll: false },
  cover: { taste: 4, aroma: 4, showAll: false },
  compact: { taste: 4, aroma: 4, showAll: true },
  full: { taste: 6, aroma: 6, showAll: true },
  radar: { taste: 4, aroma: 4, showAll: false },
  mini: { taste: 3, aroma: 3, showAll: false },
};
export const MIN_SPOKES = 3;
export const GROUP_TITLE = { taste: 'Taste', aroma: 'Aroma' };

export const hiddenLine = (n) => `+${n} fainter note${n === 1 ? '' : 's'}`;

export const axisGroup = (axis) => (TASTE_AXES.includes(axis) ? 'taste' : 'aroma');

/** The canonical axis for a bar { axis?, label? }; null when neither is known. */
export function axisOfBar(bar) {
  if (bar && typeof bar.axis === 'string' && AXES.includes(bar.axis)) return bar.axis;
  const l = String(bar?.label || '').trim().toLowerCase();
  return LABEL_TO_AXIS[l] || null;
}

/** 'taste' or 'aroma' for a bar; a bar of unknown axis counts as aroma. */
export const barGroup = (bar) => {
  if (bar && (bar.group === 'taste' || bar.group === 'aroma')) return bar.group;
  const a = axisOfBar(bar);
  return a ? axisGroup(a) : 'aroma';
};

const round3 = (v) => Math.round((Number(v) || 0) * 1000);
const orderOf = (bar) => {
  const a = axisOfBar(bar);
  return a ? AXES.indexOf(a) : AXES.length;
};

/** The one ordering: strongest first (3 decimals), ties by canonical axis order. */
export function compareBars(a, b) {
  const d = round3(b.score) - round3(a.score);
  return d !== 0 ? d : orderOf(a) - orderOf(b);
}

/** Axes at or above `floor`, strongest first by the one ordering. `scores` is { axis: number }. */
export function rankAxes(scores, { floor = FLOOR, axes = AXES } = {}) {
  return axes
    .filter((a) => (Number(scores?.[a]) || 0) >= floor && (Number(scores?.[a]) || 0) > 0)
    .map((a) => ({ axis: a, score: scores[a] }))
    .sort(compareBars)
    .map((b) => b.axis);
}

/**
 * The bars a surface shows. `bars` is any list of { axis?, label?, score, ... } (a profile's bars, or the stored
 * bars of a share card, which carry a label only). Returns
 *   { groups: [{ id: 'taste'|'aroma', title, bars }]  (only non-empty groups, taste first),
 *     bars:   the same bars flat, taste first then aroma,
 *     hidden: how many bars above the floor are not shown,
 *     canShowAll: the surface offers "show all" and something is hidden }
 * `all` shows every bar above the floor (only honoured on surfaces with showAll).
 */
export function groupBars(bars, surface = 'compact', { all = false, floor = FLOOR } = {}) {
  const cfg = SURFACES[surface] || SURFACES.compact;
  const live = (Array.isArray(bars) ? bars : [])
    .filter((b) => b && Number.isFinite(Number(b.score)) && Number(b.score) >= floor && Number(b.score) > 0)
    .map((b) => ({ ...b, group: barGroup(b) }))
    .sort(compareBars);
  const showEvery = all && cfg.showAll;
  const out = [];
  let hidden = 0;
  for (const id of ['taste', 'aroma']) {
    const mine = live.filter((b) => b.group === id);
    const shown = showEvery ? mine : mine.slice(0, cfg[id]);
    hidden += mine.length - shown.length;
    if (shown.length) out.push({ id, title: GROUP_TITLE[id], bars: shown });
  }
  return { groups: out, bars: out.flatMap((g) => g.bars), hidden, canShowAll: cfg.showAll && hidden > 0 };
}

/**
 * The axes a surface shows, from { axis: score }: { taste: [axis], aroma: [axis], axes: [axis] strongest first
 * across both groups, hidden }.
 */
export function selectAxes(scores, surface = 'full', { all = false, floor = FLOOR } = {}) {
  const bars = AXES.map((a) => ({ axis: a, score: Number(scores?.[a]) || 0 }));
  const g = groupBars(bars, surface, { all, floor });
  const pick = (id) => (g.groups.find((x) => x.id === id)?.bars || []).map((b) => b.axis);
  const axes = [...g.bars].sort(compareBars).map((b) => b.axis);
  return { taste: pick('taste'), aroma: pick('aroma'), axes, hidden: g.hidden };
}

/**
 * The axes a radar plots, in canonical order (so the shape does not jump around): the selected axes for the
 * surface (restricted to `pool` when given, e.g. only the aromas), padded with the next-strongest (then canonical-first) axes up to MIN_SPOKES so a polygon can be drawn.
 */
export function radarAxes(scores, surface = 'radar', { extra = [], floor = FLOOR, pool = AXES } = {}) {
  const inPool = (a) => pool.includes(a);
  const picked = new Set([...selectAxes(scores, surface, { floor }).axes.filter(inPool), ...extra.filter((a) => AXES.includes(a) && inPool(a))]);
  if (picked.size < MIN_SPOKES) {
    const rest = pool.map((a) => ({ axis: a, score: Number(scores?.[a]) || 0 })).sort(compareBars);
    for (const r of rest) { if (picked.size >= MIN_SPOKES) break; picked.add(r.axis); }
  }
  return pool.filter((a) => picked.has(a));
}

/**
 * Generic version for a radar whose keys are not the seventeen axes (the Cookbook card radar's chef vocabulary):
 * `signal` is Map or object key -> 0..1; returns up to `max` keys with a signal, in `canonical` order, padded to
 * MIN_SPOKES from the start of `canonical`.
 */
export function radarKeys(signal, canonical, max = 8) {
  const get = (k) => (signal instanceof Map ? signal.get(k) : signal?.[k]) || 0;
  const ranked = canonical
    .map((k, i) => ({ k, v: get(k), i }))
    .filter((r) => r.v > 0)
    .sort((a, b) => (round3(b.v) - round3(a.v)) || (a.i - b.i))
    .slice(0, max)
    .map((r) => r.k);
  const picked = new Set(ranked);
  for (const k of canonical) { if (picked.size >= Math.min(MIN_SPOKES, canonical.length)) break; picked.add(k); }
  return canonical.filter((k) => picked.has(k));
}

/**
 * shareCardLayout.js — SHARE-5. Pure, renderer-agnostic description of the recipe
 * cards people post. No DOM, no canvas, no fetch, and one import (flavorDisplay.js, the chart display rule; scripts/buildShareIndex.mjs
 * inlines it into the generated copy): the browser canvas
 * renderer and the Cloud Function (satori) both draw exactly what this returns.
 * scripts/buildShareIndex.mjs copies this file into functions/src/share/ as a
 * generated file, so keep it self-contained.
 *

 * The chart shows what flavorDisplay.groupBars picks for 'card' (3 tastes + 3 aromas) or, on a set's cover, 'cover' (4 + 4),
 * under Taste and Aroma headings; the caption adds "+N fainter notes" when bars were left out.
 * layoutCard({ format, recipe, bars, link, page })  ->  Card
 *   format  'preview' (1200x630) | 'portrait' (1080x1350) | 'tall' (1080x1920)
 *   recipe  { kind, name, lines: [{ amount, label?, key, suggested? }], method, glass?, garnish?,
 *             category?, meta?, lineCount? }   lineCount = the real number of ingredients when
 *             `lines` was cut short (the server keeps only the first few)
 *   bars    [{ label, color, score 0..1 }] strongest first, or null/[] for "no profile data"
 *           (the chart is then omitted, never drawn empty)
 *   link    the short link as printed text, e.g. "neuralflavor.web.app/r/cocktail/negroni"
 * layoutSet({ format: 'portrait'|'tall', recipe, bars, link }) -> [Card, Card, Card]
 *   1 name + flavor chart, 2 ingredients, 3 method.
 *
 * Card = { id, format, width, height, safeTop, safeBottom, background: { inner, mid, outer },
 *          primitives: [Primitive] }
 * Primitive (all coordinates in card pixels, y grows downward):
 *   { type: 'rect', x, y, w, h, fill?, stroke?, strokeWidth?, radius? }
 *   { type: 'line', x1, y1, x2, y2, color, width, dash? }
 *   { type: 'text', x, y, w, h, text, size, weight, color, font: 'hand'|'sans', align: 'left'|'center'|'right' }
 *     one line of text per primitive; (x, y, w, h) is its box, h = the line height. Layout has
 *     already wrapped, shrunk and truncated: renderers never measure or wrap.
 */


export const SITE_NAME = 'Neural Flavor';
export const CHART_CAPTION = 'flavor chart: a visual guide';
export const MORE_AT_LINK = (n) => `+${n} more at the link`;

// Chalkboard palette: the same values as src/components/inventUi.jsx / chalkTheme.js
// (a unit test keeps them equal).
export const PALETTE = {
  inner: '#1c1c1c', mid: '#0a0a0a', outer: '#050505',
  cream: '#f5efde', dim: '#bdb6a3', sub: '#8a8478', rail: '#4a4a4a', accent: '#e8c97a',
};

export const FORMATS = {
  preview: { width: 1200, height: 630, safeTop: 0, safeBottom: 0 },
  portrait: { width: 1080, height: 1350, safeTop: 0, safeBottom: 0 },
  // Stories and TikTok cover the top and bottom of the screen with their own buttons.
  tall: { width: 1080, height: 1920, safeTop: 250, safeBottom: 250 },
};

const KIND_WORD = { cocktail: 'Cocktail', sauce: 'Sauce', dish: 'Dish' };

// ---- deterministic text measuring (no DOM): per-character width, in em ------------------------
const NARROW = new Set([' ', 'i', 'l', 'j', '.', ',', ':', ';', "'", '’', '!', '|', '`']);
const MIDDLE = new Set(['f', 't', 'r', 'I', '(', ')', '-', '/', '[', ']', '·', '…']);
const WIDE = new Set(['m', 'w', 'M', 'W', '@', '%', '½']);

function emWidth(ch) {
  if (NARROW.has(ch)) return 0.3;
  if (MIDDLE.has(ch)) return 0.4;
  if (WIDE.has(ch)) return 0.9;
  if (ch >= '0' && ch <= '9') return 0.62;
  if (ch >= 'A' && ch <= 'Z') return 0.68;
  return 0.56;
}

/** Estimated width in pixels. Slightly generous on purpose, so a line that "fits" really fits in both renderers. */
export function textWidth(text, size, { font = 'sans', weight = 400 } = {}) {
  let em = 0;
  for (const ch of String(text)) em += emWidth(ch);
  const face = font === 'hand' ? 0.8 : 1;
  const bold = weight >= 600 ? 1.12 : 1;
  return em * size * face * bold;
}

const fits = (text, size, o, maxW) => textWidth(text, size, o) <= maxW;

/** Longest prefix of `text` that fits with a trailing ellipsis; `text` unchanged when it fits whole. */
export function ellipsize(text, size, o, maxW) {
  const s = String(text);
  if (fits(s, size, o, maxW)) return s;
  const chars = [...s];
  let n = chars.length;
  while (n > 0 && !fits(`${chars.slice(0, n).join('').trimEnd()}…`, size, o, maxW)) n -= 1;
  return `${chars.slice(0, n).join('').trimEnd().replace(/[,;:\-/]$/, '')}…`;
}

/** Greedy word wrap into at most `maxLines` lines; the last line is ellipsized when text is left over. */
export function wrapText(text, size, o, maxW, maxLines) {
  const words = String(text).replace(/\s+/g, ' ').trim().split(' ').filter(Boolean);
  if (!words.length) return [];
  const lines = [];
  let cur = '';
  const push = () => { if (cur) lines.push(cur); cur = ''; };
  for (const word of words) {
    const next = cur ? `${cur} ${word}` : word;
    if (fits(next, size, o, maxW)) { cur = next; continue; }
    push();
    if (fits(word, size, o, maxW)) { cur = word; continue; }
    // One word wider than the line: break it by characters.
    let rest = [...word];
    while (rest.length) {
      let n = rest.length;
      while (n > 1 && !fits(rest.slice(0, n).join(''), size, o, maxW)) n -= 1;
      lines.push(rest.slice(0, n).join(''));
      rest = rest.slice(n);
    }
  }
  push();
  if (lines.length <= maxLines) return lines;
  const kept = lines.slice(0, maxLines - 1);
  kept.push(ellipsize(lines.slice(maxLines - 1).join(' '), size, o, maxW));
  return kept;
}

/**
 * A name: shrink first (down to 70%), then wrap to two lines, then truncate with an ellipsis.
 * -> { size, lines }
 */
export function fitName(name, { size, maxW, font = 'hand', weight = 700, minScale = 0.7, maxLines = 2 }) {
  const o = { font, weight };
  const text = String(name || '').replace(/\s+/g, ' ').trim();
  for (let s = size; s >= Math.round(size * minScale); s -= 2) {
    if (fits(text, s, o, maxW)) return { size: s, lines: [text] };
  }
  const s2 = Math.round(size * 0.8);
  return { size: s2, lines: wrapText(text, s2, o, maxW, maxLines) };
}

// ---- builders ------------------------------------------------------------------------------------
const lineH = (size, lh) => Math.round(size * lh);

function text(prims, { x, y, w, text: t, size, weight = 400, color = PALETTE.cream, font = 'sans', align = 'left', lh = 1.25 }) {
  const h = lineH(size, lh);
  prims.push({ type: 'text', x: Math.round(x), y: Math.round(y), w: Math.round(w), h, text: t, size, weight, color, font, align });
  return h;
}

const kindLabel = (recipe) => {
  const word = KIND_WORD[recipe.kind] || 'Recipe';
  return recipe.category ? `${word} · ${recipe.category}` : word;
};

const cleanLines = (recipe) => (Array.isArray(recipe.lines) ? recipe.lines : []).filter((l) => l && (l.label || l.key));
const totalLines = (recipe) => Math.max(recipe.lineCount || 0, cleanLines(recipe).length);
const stepsOf = (recipe) => String(recipe.method || '').split('\n').map((s) => s.trim()).filter(Boolean);

function frame(format) {
  const f = FORMATS[format];
  if (!f) throw new Error(`unknown card format: ${format}`);
  const prims = [];
  const pad = format === 'preview' ? 48 : 72;
  prims.push({ type: 'rect', x: 18, y: 18, w: f.width - 36, h: f.height - 36, stroke: PALETTE.rail, strokeWidth: 3, radius: 10 });
  return { ...f, format, prims, pad, x0: pad, x1: f.width - pad, top: f.safeTop + (format === 'tall' ? 20 : pad - 8), bottom: f.height - f.safeBottom - (format === 'tall' ? 20 : pad - 8) };
}

function finish(id, fr) {
  return {
    id, format: fr.format, width: fr.width, height: fr.height, safeTop: fr.safeTop, safeBottom: fr.safeBottom,
    background: { inner: PALETTE.inner, mid: PALETTE.mid, outer: PALETTE.outer }, primitives: fr.prims,
  };
}

/**
 * Footer: site name and the printed link. Returns the y where the footer starts (content must end above it).
 * The link is shrunk, then split at a "/" into two lines, so it is never truncated.
 */
function footer(fr, link, page) {
  const small = fr.format === 'preview';
  const siteSize = small ? 38 : 50;
  const linkSize0 = small ? 26 : 32;
  const w = fr.x1 - fr.x0;
  const linkText = String(link || '');
  const pageText = page || '';
  const pageW = pageText ? 90 : 0;
  const siteW = textWidth(SITE_NAME, siteSize, { font: 'hand', weight: 700 });

  let linkSize = linkSize0;
  let linkLines = [linkText];
  const lo = Math.round(linkSize0 * 0.7);
  while (linkSize > lo && textWidth(linkText, linkSize, { weight: 600 }) > w) linkSize -= 1;
  if (textWidth(linkText, linkSize, { weight: 600 }) > w) {
    linkSize = linkSize0 - 6;
    const cut = linkText.lastIndexOf('/', Math.floor(linkText.length * 0.7));
    linkLines = cut > 0 ? [linkText.slice(0, cut + 1), linkText.slice(cut + 1)] : wrapText(linkText, linkSize, { weight: 600 }, w, 2);
  }
  const linkH = lineH(linkSize, 1.3);
  const sameRow = linkLines.length === 1 && siteW + 40 + textWidth(linkText, linkSize, { weight: 600 }) + pageW <= w;
  const siteH = lineH(siteSize, 1.1);
  const height = sameRow ? Math.max(siteH, linkH) : siteH + 6 + linkH * linkLines.length;
  const y = fr.bottom - height;
  fr.prims.push({ type: 'line', x1: fr.x0, y1: y - 14, x2: fr.x1, y2: y - 14, color: PALETTE.rail, width: 2 });
  if (sameRow) {
    text(fr.prims, { x: fr.x0, y: y + (height - siteH) / 2, w: siteW + 8, text: SITE_NAME, size: siteSize, weight: 700, font: 'hand', color: PALETTE.accent, lh: 1.1 });
    text(fr.prims, { x: fr.x0 + siteW + 40, y: y + (height - linkH) / 2, w: w - siteW - 40 - pageW, text: linkText, size: linkSize, weight: 600, color: PALETTE.cream, align: 'right' });
  } else {
    text(fr.prims, { x: fr.x0, y, w: siteW + 8, text: SITE_NAME, size: siteSize, weight: 700, font: 'hand', color: PALETTE.accent, lh: 1.1 });
    linkLines.forEach((ln, i) => text(fr.prims, { x: fr.x0, y: y + siteH + 6 + i * linkH, w, text: ln, size: linkSize, weight: 600, color: PALETTE.cream }));
  }
  if (pageText) text(fr.prims, { x: fr.x1 - pageW, y: y + (sameRow ? (height - siteH) / 2 : 0), w: pageW, text: pageText, size: small ? 24 : 30, color: PALETTE.sub, align: 'right' });
  return y - 14;
}

/** Heights used by the chart so callers can reserve room: the bars, one small heading per group, the caption. */
const headH = (row) => Math.round(row * 0.6);
const chartHeight = (shown, { row, caption }) => (shown.bars.length ? shown.bars.length * row + shown.groups.length * headH(row) + caption + (shown.hidden > 0 ? Math.round(caption * 0.8) : 0) + 12 : 0);

/**
 * The flavor chart: Taste and Aroma groups under small headings, labelled horizontal bars. Omitted entirely when
 * there are no bars. `shown` is flavorDisplay.groupBars output (the one display rule).
 */
function chart(fr, y, shown, { x, w, row, size }) {
  if (!shown.bars.length) return y;
  const labelW = Math.round(w * 0.3);
  const trackX = x + labelW + 16;
  const trackW = w - labelW - 16;
  const barH = Math.round(row * 0.46);
  let ry = y;
  const drawBar = (b) => {
    text(fr.prims, { x, y: ry + (row - lineH(size, 1.2)) / 2, w: labelW, text: ellipsize(b.label.charAt(0).toUpperCase() + b.label.slice(1), size, {}, labelW), size, color: PALETTE.dim, align: 'right', lh: 1.2 });
    const by = ry + Math.round((row - barH) / 2);
    fr.prims.push({ type: 'rect', x: trackX, y: by, w: trackW, h: barH, fill: 'rgba(255,255,255,0.07)', radius: 6 });
    const frac = Math.max(0.04, Math.min(1, Number(b.score) || 0));
    fr.prims.push({ type: 'rect', x: trackX, y: by, w: Math.round(trackW * frac), h: barH, fill: b.color || PALETTE.accent, radius: 6 });
    ry += row;
  };
  const headSize = Math.max(18, size - 6);
  shown.groups.forEach((g) => {
    text(fr.prims, { x, y: ry + (headH(row) - lineH(headSize, 1.2)) / 2 + 2, w, text: g.title.toUpperCase(), size: headSize, weight: 600, color: PALETTE.sub, align: 'left', lh: 1.2 });
    ry += headH(row);
    g.bars.forEach(drawBar);
  });
  const cy = ry + 4;
  const capSize = Math.max(18, size - 4);
  let end = cy + text(fr.prims, { x, y: cy, w, text: CHART_CAPTION, size: capSize, color: PALETTE.sub, align: 'left' });
  // Bars left out: say so on a second line (the caption alone fills the narrow preview column).
  if (shown.hidden > 0) end += text(fr.prims, { x, y: end, w, text: hiddenLine(shown.hidden), size: capSize, color: PALETTE.sub, align: 'left' });
  return end;
}

/** Moves the primitives from index `from` on down by dy. */
function shift(prims, from, dy) {
  for (let i = from; i < prims.length; i += 1) {
    const p = prims[i];
    if (p.type === 'line') { p.y1 += dy; p.y2 += dy; } else p.y += dy;
  }
}

/** The bars a card shows for `surface` ('card' | 'cover'): flavorDisplay.groupBars over the stored bars (label + score). */
const shownBars = (bars, surface) => groupBars((Array.isArray(bars) ? bars : []).filter((b) => b && b.label), surface);

/** Ingredient rows (amount column + name) into [y, yMax]. Ends with "+N more at the link" when it cannot fit all. */
function ingredientRows(fr, y, yMax, recipe, { x, w, size, row, amountW }) {
  const lines = cleanLines(recipe);
  const total = totalLines(recipe);
  const cap = Math.max(1, Math.floor((yMax - y) / row));
  const showAll = total <= cap && lines.length >= total;
  const shown = showAll ? lines.length : Math.min(lines.length, Math.max(0, cap - 1));
  const nameX = x + amountW + 20;
  const nameW = w - amountW - 20;
  for (let i = 0; i < shown; i += 1) {
    const l = lines[i];
    const ry = y + i * row;
    const amount = l.amount || '';
    if (amount) text(fr.prims, { x, y: ry, w: amountW, text: ellipsize(amount, size, { weight: 600 }, amountW), size, weight: 600, color: l.suggested ? PALETTE.sub : PALETTE.accent, align: 'right', lh: row / size });
    text(fr.prims, { x: nameX, y: ry, w: nameW, text: ellipsize(l.label || l.key, size, {}, nameW), size, color: PALETTE.cream, lh: row / size });
    fr.prims.push({ type: 'line', x1: x, y1: ry + row - 2, x2: x + w, y2: ry + row - 2, color: PALETTE.rail, width: 1, dash: [6, 6] });
  }
  let end = y + shown * row;
  if (total > shown) {
    text(fr.prims, { x, y: end + 4, w, text: MORE_AT_LINK(total - shown), size: Math.round(size * 0.9), color: PALETTE.accent, align: 'left', lh: row / size });
    end += row;
  }
  return end;
}

/** Method steps wrapped into [y, yMax]; ends with "+N more at the link" when cut. */
function methodBlock(fr, y, yMax, steps, { x, w, size, lh, gap }) {
  const row = lineH(size, lh);
  const o = {};
  const numW = Math.round(size * 1.5);
  const blocks = steps.map((s, i) => ({ n: `${i + 1}.`, lines: wrapText(s, size, o, w - numW, 40) }));
  const avail = yMax - y;
  let used = 0;
  let count = 0;
  for (let i = 0; i < blocks.length; i += 1) {
    const h = blocks[i].lines.length * row + (i ? gap : 0);
    const reserve = i < blocks.length - 1 ? row + gap : 0;
    if (used + h + reserve > avail) break;
    used += h;
    count += 1;
  }
  let cy = y;
  const drawBlock = (b, maxLines) => {
    const ls = b.lines.length > maxLines ? [...b.lines.slice(0, maxLines - 1), ellipsize(b.lines.slice(maxLines - 1).join(' '), size, o, w - numW)] : b.lines;
    text(fr.prims, { x, y: cy, w: numW, text: b.n, size, weight: 600, color: PALETTE.accent, lh });
    ls.forEach((ln, k) => text(fr.prims, { x: x + numW, y: cy + k * row, w: w - numW, text: ln, size, color: PALETTE.cream, lh }));
    cy += ls.length * row + gap;
  };
  if (count === 0 && blocks.length) {
    // The first step alone is too long: show its start, then point at the link.
    const keep = Math.max(1, Math.floor((avail - row - gap) / row));
    drawBlock(blocks[0], keep);
    if (blocks.length > 1) text(fr.prims, { x, y: cy, w, text: MORE_AT_LINK(blocks.length - 1), size: Math.round(size * 0.9), color: PALETTE.accent, lh });
    else text(fr.prims, { x, y: cy, w, text: 'The rest is at the link', size: Math.round(size * 0.9), color: PALETTE.accent, lh });
    return;
  }
  for (let i = 0; i < count; i += 1) drawBlock(blocks[i], 40);
  if (count < blocks.length) text(fr.prims, { x, y: cy, w, text: MORE_AT_LINK(blocks.length - count), size: Math.round(size * 0.9), color: PALETTE.accent, lh });
}

function header(fr, recipe, { nameSize, align = 'left', maxLines = 2 }) {
  let y = fr.top;
  const w = fr.x1 - fr.x0;
  const labelSize = fr.format === 'preview' ? 24 : 30;
  y += text(fr.prims, { x: fr.x0, y, w, text: ellipsize(kindLabel(recipe).toUpperCase(), labelSize, {}, w), size: labelSize, weight: 600, color: PALETTE.sub, align, lh: 1.3 }) + 6;
  const fit = fitName(recipe.name, { size: nameSize, maxW: w, maxLines });
  fit.lines.forEach((ln) => { y += text(fr.prims, { x: fr.x0, y, w, text: ln, size: fit.size, weight: 700, font: 'hand', color: PALETTE.cream, align, lh: 1.05 }); });
  return y;
}

const subline = (recipe) => [recipe.meta, recipe.glass ? `Glass: ${recipe.glass}` : '', recipe.garnish ? `Garnish: ${recipe.garnish}` : ''].filter(Boolean).join(' · ');

/**
 * The link-preview card without a chart: nothing sits on the right, so the name and ingredients use the
 * full width. Up to five ingredients: one larger column, centred in the free space. Six or more: two columns.
 */
function previewNoChart(fr, r, sub, footerTop) {
  const w = fr.x1 - fr.x0;
  let y = header(fr, r, { nameSize: 110 });
  if (sub) y += text(fr.prims, { x: fr.x0, y: y + 2, w, text: ellipsize(sub, 28, {}, w), size: 28, color: PALETTE.dim }) + 6;
  y += 14;
  const total = totalLines(r);
  const lines = cleanLines(r);
  const from = fr.prims.length;
  let end;
  if (total >= 6) {
    const gap = 56;
    const colW = Math.round((w - gap) / 2);
    const half = Math.ceil(lines.length / 2);
    const o = { size: 28, row: 40, amountW: 190 };
    const a = ingredientRows(fr, y, footerTop - 8, { ...r, lines: lines.slice(0, half), lineCount: half }, { x: fr.x0, w: colW, ...o });
    const b = ingredientRows(fr, y, footerTop - 8, { ...r, lines: lines.slice(half), lineCount: total - half }, { x: fr.x0 + colW + gap, w: colW, ...o });
    end = Math.max(a, b);
  } else {
    end = ingredientRows(fr, y, footerTop - 8, r, { x: fr.x0, w, size: 40, row: 60, amountW: 300 });
  }
  const free = footerTop - 8 - end;
  if (free > 40) shift(fr.prims, from, Math.round(free * 0.4));
  return fr;
}

// ---- the three single cards ------------------------------------------------------------------------
export function layoutCard({ format = 'portrait', recipe, bars, link = '', page = '' }) {
  const fr = frame(format);
  const r = recipe || { name: '', lines: [], method: '' };
  const w = fr.x1 - fr.x0;
  const footerTop = footer(fr, link, page);
  const sub = subline(r);

  if (format === 'preview') {
    const hasChart = shownBars(bars, 'card').bars.length > 0;
    if (!hasChart) return finish(`${format}`, previewNoChart(fr, r, sub, footerTop));
    const colW = Math.round(w * 0.56);
    const left = { ...fr, x1: fr.x0 + colW };
    let y = header(left, r, { nameSize: 92 });
    if (sub) y += text(fr.prims, { x: fr.x0, y: y + 2, w: colW, text: ellipsize(sub, 24, {}, colW), size: 24, color: PALETTE.dim }) + 6;
    y += 10;
    ingredientRows(fr, y, footerTop - 8, r, { x: fr.x0, w: colW, size: 28, row: 38, amountW: 215 });
    const cx = fr.x0 + colW + 56;
    const cw = fr.x1 - cx;
    const b = shownBars(bars, 'card');
    const total = chartHeight(b, { row: 44, caption: 30 });
    const cy = Math.max(fr.top + 40, Math.round((fr.top + footerTop - total) / 2));
    chart(fr, cy, b, { x: cx, w: cw, row: 44, size: 24 });
    return finish(`${format}`, fr);
  }

  // portrait and tall: one card with name, ingredients, chart
  const tall = format === 'tall';
  let y = header(fr, r, { nameSize: tall ? 128 : 118 });
  if (sub) y += text(fr.prims, { x: fr.x0, y: y + 4, w, text: ellipsize(sub, 30, {}, w), size: 30, color: PALETTE.dim }) + 10;
  y += 14;
  const barList = shownBars(bars, 'card');
  const row = tall ? 52 : 46;
  const chartH = chartHeight(barList, { row: tall ? 50 : 44, caption: 34 });
  const gap = barList.bars.length ? 28 : 0;
  const from = fr.prims.length;
  let end = ingredientRows(fr, y, footerTop - chartH - gap - 8, r, { x: fr.x0, w, size: tall ? 36 : 34, row, amountW: 260 });
  if (barList.bars.length) end = chart(fr, end + gap, barList, { x: fr.x0, w, row: tall ? 50 : 44, size: 28 });
  // A short recipe leaves a gap: centre the ingredients and chart in the free space instead of hugging the top.
  const free = footerTop - 8 - end;
  if (free > 60) shift(fr.prims, from, Math.round(free * 0.4));
  return finish(format, fr);
}

// ---- the set of three ---------------------------------------------------------------------------------
export function layoutSet({ format = 'portrait', recipe, bars, link = '' }) {
  if (format === 'preview') throw new Error('a set is portrait or tall');
  const r = recipe || { name: '', lines: [], method: '' };
  const tall = format === 'tall';

  // 1: name and chart
  const a = frame(format);
  const w = a.x1 - a.x0;
  const aFoot = footer(a, link, '1/3');
  const barList = shownBars(bars, 'cover');
  const names = fitName(r.name, { size: tall ? 150 : 136, maxW: w });
  const labelSize = 32;
  const nameBlock = names.lines.length * lineH(names.size, 1.05);
  const n = totalLines(r);
  const info = [n ? `${n} ingredient${n === 1 ? '' : 's'}` : '', subline(r)].filter(Boolean).join(' · ');
  const chartH = chartHeight(barList, { row: 58, caption: 36 });
  const blockH = labelSize * 1.3 + 8 + nameBlock + (info ? 52 : 0) + (barList.bars.length ? 56 + chartH : 0);
  let y = Math.max(a.top + 20, Math.round((a.top + aFoot - blockH) / 2));
  y += text(a.prims, { x: a.x0, y, w, text: ellipsize(kindLabel(r).toUpperCase(), labelSize, {}, w), size: labelSize, weight: 600, color: PALETTE.sub, align: 'center', lh: 1.3 }) + 8;
  names.lines.forEach((ln) => { y += text(a.prims, { x: a.x0, y, w, text: ln, size: names.size, weight: 700, font: 'hand', color: PALETTE.cream, align: 'center', lh: 1.05 }); });
  if (info) y += text(a.prims, { x: a.x0, y: y + 10, w, text: ellipsize(info, 30, {}, w), size: 30, color: PALETTE.dim, align: 'center' }) + 42;
  if (barList.bars.length) chart(a, y + 14, barList, { x: a.x0, w, row: 58, size: 30 });

  // 2: ingredients
  const b = frame(format);
  const bFoot = footer(b, link, '2/3');
  let by = b.top + 10;
  by += text(b.prims, { x: b.x0, y: by, w, text: ellipsize(r.name, 36, {}, w), size: 36, color: PALETTE.sub, lh: 1.3 }) + 4;
  by += text(b.prims, { x: b.x0, y: by, w, text: 'Ingredients', size: 96, weight: 700, font: 'hand', color: PALETTE.cream, lh: 1.05 }) + 16;
  const end = ingredientRows(b, by, bFoot - (r.garnish ? 70 : 12), r, { x: b.x0, w, size: 40, row: 62, amountW: 320 });
  if (r.garnish) text(b.prims, { x: b.x0, y: Math.min(end + 14, bFoot - 56), w, text: ellipsize(`Garnish: ${r.garnish}`, 32, {}, w), size: 32, color: PALETTE.dim });

  // 3: method
  const c = frame(format);
  const cFoot = footer(c, link, '3/3');
  let cy = c.top + 10;
  cy += text(c.prims, { x: c.x0, y: cy, w, text: ellipsize(r.name, 36, {}, w), size: 36, color: PALETTE.sub, lh: 1.3 }) + 4;
  cy += text(c.prims, { x: c.x0, y: cy, w, text: 'Method', size: 96, weight: 700, font: 'hand', color: PALETTE.cream, lh: 1.05 }) + 16;
  const steps = stepsOf(r);
  if (steps.length) methodBlock(c, cy, cFoot - 8, steps, { x: c.x0, w, size: 36, lh: 1.38, gap: 18 });
  else text(c.prims, { x: c.x0, y: cy, w, text: 'The full recipe is at the link.', size: 36, color: PALETTE.dim });

  return [finish('1', a), finish('2', b), finish('3', c)];
}

/** A card for a link that points at nothing we can show (unknown, removed): the site name and what it is. */
export function layoutSiteCard({ link = 'neuralflavor.web.app' } = {}) {
  const fr = frame('preview');
  const w = fr.x1 - fr.x0;
  const name = fitName(SITE_NAME, { size: 150, maxW: w });
  let y = 190;
  y += text(fr.prims, { x: fr.x0, y, w, text: name.lines[0], size: name.size, weight: 700, font: 'hand', color: PALETTE.accent, align: 'center', lh: 1.05 }) + 14;
  y += text(fr.prims, { x: fr.x0, y, w, text: 'Cocktails, sauces and dishes, built from what pairs well', size: 32, color: PALETTE.cream, align: 'center' }) + 24;
  text(fr.prims, { x: fr.x0, y, w, text: link, size: 28, weight: 600, color: PALETTE.dim, align: 'center' });
  return finish('site', fr);
}
